<?php
namespace App\Application\Settings\Services;
use App\Application\Settings\DTOs\SettingData;use App\Domain\Contracts\Repositories\SettingRepositoryInterface;use App\Domain\Models\Setting;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\DB;use InvalidArgumentException;
class SettingService{public function __construct(private readonly SettingRepositoryInterface $repo){}public function public(?string $group=null){return collect($this->repo->all($group))->filter(fn(Setting $s)=>!$s->is_locked)->mapWithKeys(fn(Setting $s)=>[$s->key=>$s->typedValue()]);}public function admin(?string $group=null){return $this->repo->all($group);}public function get(string $key):mixed{return Cache::remember('setting:'.$key,3600,fn()=>($s=$this->repo->find($key))?->typedValue());}public function save(SettingData $d):Setting{return DB::transaction(function()use($d){$s=$this->repo->find($d->key);if($s?->is_locked)throw new InvalidArgumentException('هذا الإعداد محمي ولا يمكن تعديله.');$value=in_array($d->type,['json','array'],true)?json_encode($d->value,JSON_UNESCAPED_UNICODE):($d->type==='boolean'?(bool)$d->value:(string)$d->value);$s=$this->repo->upsert(['key'=>$d->key,'display_name'=>$d->displayName,'value'=>$value,'type'=>$d->type,'group'=>$d->group,'is_locked'=>$d->locked]);Cache::forget('setting:'.$d->key);return $s;});}}
